//! Saved-column checker using independent affine point generation and frozen jets.
#[path="../feature-native-division/lib.rs"]mod jets;
use std::collections::BTreeSet;
fn mul(a:u64,b:u64,p:u64)->u64{((a as u128*b as u128)%p as u128)as u64}
fn pow(mut a:u64,mut n:u64,p:u64)->u64{let mut v=1;while n>0{if n&1!=0{v=mul(v,a,p);}n>>=1;if n>0{a=mul(a,a,p);}}v}
fn add(p:u64,a:u64,u:Option<[u64;2]>,v:Option<[u64;2]>)->Option<[u64;2]>{let(Some([x,y]),Some([xx,yy]))=(u,v)else{return u.or(v)};if x==xx&&(y+yy)%p==0{return None;}let(n,d)=if x==xx{((mul(3,mul(x,x,p),p)+a)%p,(2*y)%p)}else{((yy+p-y)%p,(xx+p-x)%p)};let m=mul(n,pow(d,p-2,p),p);let z=(mul(m,m,p)+2*p-x-xx)%p;Some([z,(mul(m,(x+p-z)%p,p)+p-y)%p])}
fn main(){let path=std::env::args().nth(1).unwrap();let raw=std::fs::read_to_string(path).unwrap();let mut expected=std::collections::BTreeMap::new();
 for(p,a,b,r,base,indices)in[(5,2,1,7,[0,1],vec![4,2]),(7,0,3,13,[1,2],vec![7,4,1]),(509,2,10,479,[3,68],vec![240,22,10])]{let mut point=None;for i in 0..r{for &n in &indices{expected.insert((p,i,n),(a,b,r,point));}point=add(p,a,point,Some(base));}assert!(point.is_none());}
 let mut lines=raw.lines();assert_eq!(lines.next().unwrap(),"p\tr\toffset\tn\tx\ty\tnumerator\tdenominator\tdirect\tmethod");let mut seen=BTreeSet::new();for l in lines{let f:Vec<_>=l.split('\t').collect();assert_eq!(f.len(),10);let p=f[0].parse::<u64>().unwrap();let r=f[1].parse::<u64>().unwrap();let i=f[2].parse::<u64>().unwrap();let n=f[3].parse::<u64>().unwrap();let key=(p,i,n);assert!(seen.insert(key));let &(a,b,rr,point)=expected.get(&key).unwrap();assert_eq!(r,rr);let xy=[f[4].parse::<i64>().unwrap(),f[5].parse::<i64>().unwrap()];assert_eq!(xy,point.map(|[x,y]|[x as i64,y as i64]).unwrap_or([-1,-1]));let num=f[6].parse::<u64>().unwrap();let den=f[7].parse::<u64>().unwrap();let stored=f[8].parse::<u64>().unwrap();assert!(num<p&&den>0&&den<p&&stored<p);
  let value=match point{None=>0,Some([x,y])=>{let mut d=jets::Division::new(p,a,b,x,y).unwrap();let c=d.phase(r).unwrap();mul(d.value(n),pow(c,((n as u128*n as u128)%(p-1)as u128)as u64,p),p)}};assert_eq!(stored,value);assert_eq!(num,mul(value,den,p));let method=if [0,1,2,r-1].contains(&i){"anchor"}else{"recurrence"};assert_eq!(f[9],method);
 }assert_eq!(seen.len(),expected.len());assert_eq!(seen.len(),1490);println!("checked_values=1490 complete_prime_field_subgroups=3 affine_point_order_checks=3");}
